noncomputable def fixedEnergy (charge energy : A02.Occupation ι → ℤ) (N E : ℤ) :
    Submodule ℂ (A02.FockSpace ι) :=
  coordinateSpace {S | charge S = N ∧ energy S = E}

noncomputable def budget (charge energy : A02.Occupation ι → ℤ) (N K : ℤ) :
    Submodule ℂ (A02.FockSpace ι) :=
  coordinateSpace {S | charge S = N ∧ energy S ≤ K}

noncomputable def chargeBox (charge energy : A02.Occupation ι → ℤ) (K : ℤ) (Nmax : ℕ) :
    Submodule ℂ (A02.FockSpace ι) :=
  coordinateSpace {S | energy S ≤ K ∧ |charge S| ≤ (Nmax : ℤ)}

def restrictedMap (U W : Submodule ℂ V) (A : Module.End ℂ V)
    (hA : ∀ v ∈ U, A v ∈ W) : U →ₗ[ℂ] W :=
  (A.domRestrict U).codRestrict W (fun v => hA v v.property)

noncomputable def partitionState (h : ℕ) (Ns : σ → ℤ) {K : ℕ}
    (p : JointPartitions σ K) : FockSpace σ h :=
  wordState h Ns (fun ν => Ch11.partitionList (p.val ν).2)

def integerLift (h : ℕ) {V : Type*}
    (f : ZMod (2 * h) → V) (x : ℤ) : V :=
  f (x : ZMod (2 * h))

def creatorToSeaLetter (h : ℕ) (k : Ch01.Band (2 * h)) :
    Bool × Ch01.Band (2 * h) :=
  (decide (0 < k.val), k)

def annihilatorToSeaLetter (h : ℕ) (k : Ch01.Band (2 * h)) :
    Bool × Ch01.Band (2 * h) :=
  (decide (k.val ≤ 0), k)

def bilinearWord (h : ℕ) (a b : Ch01.Band (2 * h)) :
    List (Bool × Ch01.Band (2 * h)) :=
  [creatorToSeaLetter h a, annihilatorToSeaLetter h b]

def seaWickWeight (h M : ℕ) (k : Ch01.Band (2 * h)) : ℤ :=
  if k.val ≤ 0 then 1 + 2 * min (M : ℤ) (-k.val)
  else 1 + 2 * min (M : ℤ) (k.val - 1)

noncomputable def seaWickWord (h : ℕ) (ν : σ)
    (w : List (Bool × Ch01.Band (2 * h))) : A05.Operators σ h :=
  let creators := w.filter (fun l => l.1)
  let annihilators := w.filter (fun l => !l.1)
  ((-1 : ℂ) ^ seaInversions h w) •
    (((creators ++ annihilators).map (evalSeaLetter h ν)).prod)

def nonResonant {ι : Type*} (inLow : ι → Bool) (E : ι → ℝ)
    (Voff : Matrix ι ι ℂ) : Prop :=
  ∀ i j : ι, inLow i ≠ inLow j → Voff i j ≠ 0 → E i ≠ E j

def exactShellSet (h : ℕ) (Ns : σ → ℤ) (K : ℕ) :
    Set (A05.Occupation σ h) :=
  {S | (∀ ν, Ch07.relativeCharge h (Ch07.speciesConfiguration h S ν) = Ns ν) ∧
    Ch07.totalExcitation h S = (K : ℤ)}

noncomputable def creation (i : ι) : Module.End ℂ (A02.FockSpace ι) :=
  A02.extendBasis fun S =>
    if i ∈ S then 0 else fermionSign i S • A02.ket (insert i S)

def hopSign (h : ℕ) (z : Ch01.Band (2*h) × Ch01.Band (2*h)) : ℂ :=
  Ch04.fermionSign z.2 (Ch05.seaConfiguration (2*h)) *
    Ch04.fermionSign z.1 ((Ch05.seaConfiguration (2*h)).erase z.2)

def fourSectorMargin (h K : ℕ) (Ns : σ → ℤ) (ν η : σ) : Prop :=
  A05.r2 h K Ns ∧ A05.r2 h K (lowerCharge Ns ν) ∧
    A05.r2 h K (lowerCharge Ns η) ∧ A05.r2 h K (lowerCharge (lowerCharge Ns ν) η)

def budgetSet (h : ℕ) (Ns : σ → ℤ) (K : ℕ) : Set (A05.Occupation σ h) :=
  {S | (∀ ν, Ch07.relativeCharge h (Ch07.speciesConfiguration h S ν) = Ns ν) ∧
    Ch07.totalExcitation h S ≤ (K : ℤ)}

noncomputable def zeroModeEnergyScalar {σ : Type*} (h : ℕ)
    (vF g4 g2 mu : ℝ) (branches : A06.Branches σ) (Ns : σ → ℤ) : ℝ :=
  let L : ℝ := ((2 * h : ℕ) : ℝ)
  let nr : ℝ := (Ns branches.rightSpecies : ℝ)
  let nl : ℝ := (Ns branches.leftSpecies : ℝ)
  (2 * Real.pi * vF / L) * (nr * (nr + 1) / 2 + nl * (nl + 1) / 2) +
    (g4 / (2 * L)) * (nr ^ 2 + nl ^ 2) +
    (g2 / L) * nr * nl -
    mu * (nr + nl)

noncomputable def symmetricZeroModeScalar {σ : Type*} (h : ℕ)
    (vF g4 g2 : ℝ) (branches : A06.Branches σ) (Ns : σ → ℤ) : ℝ :=
  let L : ℝ := ((2 * h : ℕ) : ℝ)
  let nr : ℝ := (Ns branches.rightSpecies : ℝ)
  let nl : ℝ := (Ns branches.leftSpecies : ℝ)
  (Real.pi * v1Velocity vF g4 / L) * (nr ^ 2 + nl ^ 2) +
    (g2 / L) * nr * nl

def LuttingerParams.toHyperbolicPair {v1 v2 : ℝ} (lp : LuttingerParams v1 v2) :
    HyperbolicPair :=
  HyperbolicPair.ofParams lp

private noncomputable def targetZeroOccupation (l : Ch01.Band 4) :
    A05.Occupation (Fin 2) 2 :=
  insert (0,l) ((A05.groundConfiguration 2 witnessZero).erase (1,targetZeroMn))

def blochWireMatrixHomog (v kx t1 t2 r c s : ℤ) : Matrix (Fin 2) (Fin 2) GaussianInt :=
  !![⟨v * kx, 0⟩, ⟨t1 * r + t2 * c, -(t2 * s)⟩;
     ⟨t1 * r + t2 * c, t2 * s⟩, ⟨-(v * kx), 0⟩]

def wireMassEntry (n : ℕ) (t1 t2 : ℤ) (y z : ℕ) : ℤ :=
  if y < n ∧ z < n then
    if y + 1 = z then (if y % 2 = 0 then t1 else t2)
    else if z + 1 = y then (if z % 2 = 0 then t1 else t2)
    else 0
  else 0

def wireMassSqEntry (n : ℕ) (t1 t2 : ℤ) (y z : ℕ) : ℤ :=
  if y < n ∧ z < n then
    if y = z then (if y = 0 ∨ y + 1 = n then t1 * t1 else t1 * t1 + t2 * t2)
    else if y + 2 = z ∨ z + 2 = y then t1 * t2
    else 0
  else 0

def obcDiffEntry (n y z : ℕ) : ℤ :=
  if y + 1 < n then diffLinkEntry y z
  else if y + 1 = n then (if y = z then -1 else 0)
  else 0

def pbcDiffEntry (n y z : ℕ) : ℤ :=
  if y + 1 < n then diffLinkEntry y z
  else if y + 1 = n then (if z = 0 then 1 else 0) - (if y = z then 1 else 0)
  else 0

def pbcShiftEntry (n y z : ℕ) : ℤ :=
  if y + 1 < n then shiftLinkEntry y z
  else if y + 1 = n then (if z = 0 then 1 else 0) + (if y = z then 1 else 0)
  else 0

def staggeredCSVarOBC (n : ℕ) (twoNu0 : ℤ) (y : ℕ) : ℤ :=
  if y = 0 then twoNu twoNu0 0
  else if y + 1 = n then -twoNu twoNu0 (n - 2)
  else twoNu twoNu0 y - twoNu twoNu0 (y - 1)

def mutualCSAction (T X N : ℕ) (a0 a1 a2 A0 A1 A2 : ℕ → ℕ → ℕ → ℤ) : ℤ :=
  ∑ t ∈ Finset.range T, ∑ x ∈ Finset.range X, ∑ y ∈ Finset.range N,
    mutualCSIntegrand T X N a0 a1 a2 A0 A1 A2 t x y

def commTildePhiHalfPi (sgnX : ℤ) (y y' : ℕ) (s s' : ℤ) : ℤ :=
  2 * ((if y = y' then paritySign y * ((if s = s' then sgnX else 0) + speciesEps s s') else 0) +
    skewSignEntry y y')

def commPhiC_HalfPi (m : ℕ) (sgnX : ℤ) (y y' : ℕ) : ℤ :=
  ∑ j ∈ Finset.range (2 * m), ∑ k ∈ Finset.range (2 * m),
    dualityEntry y j * commTildeC_HalfPi sgnX j k * dualityEntry y' k

def fkPairOp (y k : ℕ) : ℤ :=
  if k = 3 * y then -1 else if k = 3 * y + 1 then -1
  else if k = 3 * y + 3 then 1 else if k = 3 * y + 4 then 1 else 0

def fkProximityOp (y k : ℕ) : ℤ :=
  if k = 3 * y + 2 then -1 else if k = 3 * y + 3 then 1
  else if k = 3 * y + 4 then 1 else if k = 3 * y + 5 then -1 else 0

def tPfaffianPairTarget (y z : ℕ) : ℤ :=
  paritySign y * (if z = 3 * y then 1 else if z = 3 * y + 1 then -3
    else if z = 3 * y + 2 then 4 else if z = 3 * y + 3 then -3
    else if z = 3 * y + 4 then 1 else 0)

def tPfaffianCone2HopTarget (y z : ℕ) : ℤ :=
  paritySign y * (if z = 3 * y + 2 then 1 else if z = 3 * y + 3 then -2
    else if z = 3 * y + 4 then 2 else if z = 3 * y + 5 then -1 else 0)

def IsPairing {n : ℕ} (P : Pairing n) : Prop :=
  (∀ e ∈ P, e.1 < e.2) ∧
  (∀ i : Fin n, ∃! j : Fin n, (i, j) ∈ P ∨ (j, i) ∈ P)

def Good (V : Finset α) (P : Finset (α×α)) : Prop :=
  (∀ e∈P, e.1 < e.2) ∧
  ∀ i, (i∈V ↔ ∃j, R P i j) ∧ (∀ j k, R P i j → R P i k → j=k)

noncomputable def jointTensorFunctional {M : ℕ}
    (_hp : Bosonize.Ch18.HyperbolicPair) (N : Charge) : JointCarrier M →ₗ[ℂ] ℂ :=
  TensorProduct.lift
    { toFun := fun v =>
        { toFun := fun p => v N * MvPolynomial.lcoeff ℂ 0 p
          map_add' := by intro p q; simp [mul_add]
          map_smul' := by intro z p; simp only [map_smul, RingHom.id_apply, smul_eq_mul]; ring }
      map_add' := by intro v w; ext p; simp [add_mul]
      map_smul' := by intro z v; ext p; simp [mul_assoc] }

def rightOscillatorParity {M : ℕ}
    (k : Bosonize.A08.OscMode M →₀ ℕ) : ℂ :=
  (-1 : ℂ) ^ rightOscillatorDegree k

def inverseBranches {M : ℕ} : Word M → Finset (Word M)
  | [] => {[]}
  | g :: tail => (inverseBranches tail).biUnion fun branch =>
      {g :: branch, flipGenerator g :: branch}

def branchCoefficient {M : ℕ} (c s : ℝ) (w v : Word M) : ℂ :=
  ((List.zip w v).map fun p =>
    if p.1 = p.2 then (c : ℂ)
    else if flipGenerator p.1 = p.2 then (s : ℂ) else 0).prod

def parts {M : ℕ} (r : Bosonize.A08.OscMode M →₀ ℕ)
    (o : Bosonize.A06.Orientation) : List ℕ :=
  (List.finRange M).flatMap fun i => List.replicate (r (o,i)) (i.val+1)

noncomputable def monoE {σ : Type*} [Fintype σ] [LinearOrder σ] {M : ℕ}
    (species : Bosonize.A06.Orientation → σ) (r : Bosonize.A08.OscMode M →₀ ℕ) : σ → ℤ :=
  fun ν => (multiIndexParts M species r ν).sum

noncomputable def smallEigenvalue (j : Fin 8) : ℝ :=
  if j = 0 then smallEnergy
  else if j = 5 then Real.pi / 8 * (17 + Real.sqrt 514)
  else if j = 1 ∨ j = 2 then 17 * (Real.pi / 8) else 34 * (Real.pi / 8)

variable {U H : Type*}
  [NormedAddCommGroup U] [InnerProductSpace ℂ U] [FiniteDimensional ℂ U]
  [NormedAddCommGroup H] [InnerProductSpace ℂ H] [FiniteDimensional ℂ H]

def gradedSectorSet (h : ℕ) (Ns : SpinBranch → ℤ) (es : SpinBranch → ℕ) :
    Set (A05.Occupation SpinBranch h) :=
  {S | ∀ ν, Ch07.relativeCharge h (Ch07.speciesConfiguration h S ν) = Ns ν ∧
            Ch07.excitationEnergy h (Ch07.speciesConfiguration h S ν) = (es ν : ℤ)}

noncomputable def gradedSectorSpace (h : ℕ) (Ns : SpinBranch → ℤ) (es : SpinBranch → ℕ) :
    Submodule ℂ (A05.FockSpace SpinBranch h) :=
  @A03.coordinateSpace (A05.Mode SpinBranch h) _ instDecidableEqProd (gradedSectorSet h Ns es)

def productCutoffSet (h : ℕ) (Ns : SpinBranch → ℤ) (K : ℕ) :
    Set (A05.Occupation SpinBranch h) :=
  {S | ∀ ν, Ch07.relativeCharge h (Ch07.speciesConfiguration h S ν) = Ns ν ∧
            Ch07.excitationEnergy h (Ch07.speciesConfiguration h S ν) ≤ (K : ℤ)}

noncomputable def productCutoffSpace (h : ℕ) (Ns : SpinBranch → ℤ) (K : ℕ) :
    Submodule ℂ (A05.FockSpace SpinBranch h) :=
  @A03.coordinateSpace (A05.Mode SpinBranch h) _ instDecidableEqProd (productCutoffSet h Ns K)

def swOffDiagMatrix {ι : Type*} [DecidableEq ι] (inLow : ι → Bool) (V : Matrix ι ι ℂ) :
    Matrix ι ι ℂ :=
  fun i j => if inLow i ≠ inLow j then V i j else 0

noncomputable def spinfulFreeHamiltonian (h : ℕ) : A05.Operators SpinBranch h :=
  @A03.diagonal (A05.Mode SpinBranch h) _ instDecidableEqProd
    (fun S => ((∑ ν : SpinBranch, Ch07.relativeEnergy h (Ch07.speciesConfiguration h S ν) : ℤ) : ℂ))

noncomputable def umklappBlockProj (h : ℕ) (hh : 0 < h) : A05.Operators SpinBranch h :=
  @A03.coordinateProjection (A05.Mode SpinBranch h) _ instDecidableEqProd
    {A05.groundConfiguration h (fun _ => 0), umklappTargetConfig h hh}

noncomputable def umklappBlockS1Op (h : ℕ) (hh : 0 < h) (gU : ℝ) : A05.Operators SpinBranch h :=
  let c : ℂ := -((gU : ℂ) / ((2 * (h : ℂ)) ^ 2))
  let s : ℂ := c / (2 * (h : ℂ))
  @A02.extendBasis (A05.Mode SpinBranch h) _ instDecidableEqProd (fun S =>
    if S = A05.groundConfiguration h (fun _ => 0) then
      s • umklappZeroChargeWitness h hh
    else if S = umklappTargetConfig h hh then
      (-s) • A05.groundKet h (fun _ => 0)
    else 0)

noncomputable def SpinfulHyperbolicBlocks.Kc {vF g4c g2c g4s g2s : ℝ}
    (B : SpinfulHyperbolicBlocks vF g4c g2c g4s g2s) : ℝ :=
  Ch18.luttingerG (Ch18.HyperbolicPair.ofParams B.charge)

noncomputable def SpinfulHyperbolicBlocks.Ks {vF g4c g2c g4s g2s : ℝ}
    (B : SpinfulHyperbolicBlocks vF g4c g2c g4s g2s) : ℝ :=
  Ch18.luttingerG (Ch18.HyperbolicPair.ofParams B.spin)

noncomputable def chargeSector (h : ℕ) (Ns : SpinBranch → ℤ) :
    Submodule ℂ (A05.FockSpace SpinBranch h) :=
  @A03.coordinateSpace (A05.Mode SpinBranch h) _ instDecidableEqProd
    {S | ∀ ν, Ch07.relativeCharge h (Ch07.speciesConfiguration h S ν) = Ns ν}

noncomputable def umklappZeroChargeWitness (h : ℕ) (hh : 0 < h) :
    A05.FockSpace SpinBranch h :=
  @A02.ket (A05.Mode SpinBranch h) _ instDecidableEqProd (umklappTargetConfig h hh)

def speciesChargeBoxSet (h K : ℕ) (B : SpinBranch → ℕ) : Set (A05.Occupation SpinBranch h) :=
  {S | (∀ ν, |Ch07.relativeCharge h (Ch07.speciesConfiguration h S ν)| ≤ (B ν : ℤ)) ∧
    Ch07.totalExcitation h S ≤ (K : ℤ)}

noncomputable def speciesChargeBox (h K : ℕ) (B : SpinBranch → ℕ) :
    Submodule ℂ (A05.FockSpace SpinBranch h) :=
  @A03.coordinateSpace (A05.Mode SpinBranch h) _ instDecidableEqProd (speciesChargeBoxSet h K B)
